import definitions from "./palette.js";
import { entriesFromObject } from "./utils/shared.js";
const { version: _, ...jsonFlavor } = definitions;
export const version = definitions.version;
export const flavors = entriesFromObject(jsonFlavor).reduce((acc, [flavorName, flavor]) => {
    acc[flavorName] = {
        ...flavor,
        colorEntries: entriesFromObject(flavor.colors),
        ansiColorEntries: entriesFromObject(flavor.ansiColors),
    };
    return acc;
}, {});
export const flavorEntries = entriesFromObject(flavors);
